14	        data: DataSeriesExtended;
15	        /** Will appear after processing series */
16	        $c: DataSeriesExtended;
17	        /** Will appear after processing series if serie values normalized */
18	        normalizedData?: DataSeries;
19	        /** Does line have only null values */
20	        empty?: boolean;
21	        /** Real values count */
22	        count: number;
23	        /** Values sum */
24	        sum: number;
25	        /** Average value */
26	        avg: number;
27	        /** Get focus color */
28	        getFocusedColor: (y: Yagr, idx: number) => string;
29	        /** Current focus state */
30	        _focus?: boolean | null;
31	        /** Is series data transformd */
32	        _transformed?: boolean;
33	        /** Temporary hidden flag for showInGraph */
34	        _tempHidden?: boolean;
35	    }
36	    interface Axis {
37	        getFormatter?: (range: number) => (value: number) => string;
38	    }
39	}
40	/**
41	 * Main Yagr chart config
42	 */
43	export interface YagrConfig {
44	    /** Main chart visualization config */
45	    chart: YagrChartOptions;
46	    /** Graph title style. To customize other properties use CSS */
47	    title: {
48	        text: string;
49	        fontSize?: number;
50	    };
51	    /** Chart inline legend configuration */
52	    legend: LegendOptions;
53	    /** Config for axes. Determines style and labeling */
54	    axes: Record<string, AxisOptions>;
55	    /** Options for cursor plugin. Determines style, visibility and points render */
56	    cursor: CursorOptions;
57	    /** Timestamps */
58	    timeline: number[];
59	    /** Tooltip config. Detemines tooltip's behavior */
60	    tooltip: Partial<TooltipOptions>;
61	    /** Grid options (applies to all axes, can be overrided by axis.grid). */
62	    grid: UAxis.Grid;
63	    /** Marker visualisation options */
64	    markers: MarkersOptions;
65	    /** Scales options */
66	    scales: Record<string, Scale>;
67	    /** PlotLines plugin options */
68	    plotLines: PlotLineOptions;
69	    /** Raw series data and options */
70	    series: RawSerieData[];
71	    /** UPlot bands for grouping series*/
72	    bands?: Band[];
73	    /** uPlot hooks + Yagr hooks */
74	    hooks: YagrHooks;
75	    /** Yagr data processing options */
76	    processing?: ProcessingSettings;
77	    /** uPlot options transform method */
78	    editUplotOptions?: (opts: Options) => Options;
79	    /** Additional Yagr plugins */
80	    plugins: Record<string, YagrPlugin>;
81	}
82	export type MinimalValidConfig = Partial<YagrConfig> & {
83	    timeline: Number[];
84	    series: RawSerieData[];
85	};
86	type CommonHookHandlerArg<T> = T & {
87	    chart: Yagr;
88	};
89	export type HookHandler<Data> = ((a: CommonHookHandlerArg<Data>) => void)[];
90	export type LoadHandlerArg = CommonHookHandlerArg<{
91	    meta: YagrMeta;
92	}>;
93	export type OnSelectHandlerArg = CommonHookHandlerArg<{
94	    from: number;
95	    to: number;
96	}>;
97	export type ErrorHandlerArg = CommonHookHandlerArg<{
98	    type: YagrState['stage'];
99	    error: Error;
100	}>;
