102	    meta: Pick<YagrMeta, 'processTime'>;
103	}>;
104	export type InitedHandlerArg = CommonHookHandlerArg<{
105	    meta: Pick<YagrMeta, 'initTime'>;
106	}>;
107	export type DisposeHandlerArg = CommonHookHandlerArg<{}>;
108	export type ResizeHandlerArg = CommonHookHandlerArg<{
109	    entries: ResizeObserverEntry[];
110	}>;
111	export type ScaleUpdateHandlerArg = CommonHookHandlerArg<{
112	    scales: Record<string, {
113	        min: number;
114	        max: number;
115	    }>;
116	}>;
117	export interface InternalYargHooks {
118	    load?: HookHandler<{
119	        meta: YagrMeta;
120	    }>;
121	    onSelect?: HookHandler<{
122	        from: number;
123	        to: number;
124	    }>;
125	    error?: HookHandler<{
126	        error: Error;
127	        stage: YagrState['stage'];
128	    }>;
129	    processed?: HookHandler<{
130	        meta: Pick<YagrMeta, 'processTime'>;
131	    }>;
132	    inited?: HookHandler<{
133	        meta: Pick<YagrMeta, 'initTime'>;
134	    }>;
135	    dispose?: HookHandler<{}>;
136	    resize?: HookHandler<{
137	        entries: ResizeObserverEntry[];
138	    }>;
139	    stage?: HookHandler<{
140	        stage: YagrState['stage'];
141	    }>;
142	    scaleUpdate?: HookHandler<{
143	        scales: Record<string, {
144	            min: number;
145	            max: number;
146	        }>;
147	    }>;
148	}
149	export type YagrHooks = Hooks.Arrays & InternalYargHooks;
150	export interface ProcessingInterpolation {
151	    /** Interpolation type */
152	    /**
153	     * - previous: takes previous existing value
154	     * - left: takes previous existing value except for last point
155	     * - next: takes next existing value
156	     * - right: takes next existing value except for first point
157	     * - linear: calcs value by linear interpolation
158	     * - closes: takes closes existing value
159	     */
160	    type: 'previous' | 'left' | 'next' | 'right' | 'linear' | 'closest';
161	    /** Cursor and tooltip snapToValue option */
162	    snapToValues?: SnapToValue | false;
163	    /** Values to interpolate */
164	    value?: unknown;
165	}
166	export interface ProcessingSettings {
167	    /** Should interpolate missing data (default: undefined) */
168	    interpolation?: ProcessingInterpolation;
169	    /** Values to map as nulls as key-value object */
170	    nullValues?: Record<string, string | null>;
171	}
172	/**
173	 * Main chart visualization config
174	 */
175	export interface YagrChartOptions {
176	    /** Common series options, could be overriden by series.<option> field */
177	    series?: SeriesOptions;
178	    size?: {
179	        /** width (by default: 100% of root) */
180	        width?: number;
181	        /** height (by default: 100% of root) */
182	        height?: number;
183	        /** padding in css px [top, right, bottom, left] (by default: utils.chart.getPaddingByAxes) */
184	        padding?: [number, number, number, number];
185	        /** Should chart redraw on container resize (default: true) */
186	        adaptive?: boolean;
187	        /** Debounce timer for ResizeObserver to trigger: (default 100 ms) */
188	        resizeDebounceMs?: number;
189	    };
190	    select?: {
191	        /** Minial width to catch selection */
192	        minWidth?: number;
193	        /** Enable native uPlot zoom (default: true) */
194	        zoom?: boolean;
195	    };
196	    appearance?: {
197	        /** Order of drawing. Impacts on zIndex of entity. (axes, series) by default */
198	        drawOrder?: DrawKey[];
199	        /** Theme (default: 'light') */
200	        theme?: YagrTheme;
201	        /** Locale */
202	        locale?: SupportedLocales | Record<string, string>;
203	    };
204	    /** 1 for milliseconds, 1e-3 for seconds (default: 1) */
205	    timeMultiplier?: 1 | 1e-3;
206	}
207	export type ChartType = 'area' | 'line' | 'column' | 'dots';
208	/** Data values of lines */
209	export type DataSeriesExtended = (number | string | null)[];
210	export type DataSeries = (number | null)[];
211	export interface CommonSeriesOptions {
212	    /** Visualisation type */
213	    type?: ChartType;
214	    /** Is series visible */
215	    show?: boolean;
216	    /** Color of serie */
217	    color?: string;
218	    /** Cursor options for single serie */
219	    cursorOptions?: Pick<CursorOptions, 'markersSize' | 'snapToValues'>;
220	    /** Formatter for serie value */
221	    formatter?: (value: string | number | null, serie: Series) => string;
222	    /** Line precision */
223	    precision?: number;
224	    /** Snap dataIdx value (default: closest) */
225	    snapToValues?: SnapToValue | false;
226	    /** Stacking groups */
227	    stackGroup?: number;
228	    /** Title of serie */
229	    title?: string | ((sIdx: number) => string);
230	    /** Series data transformation */
231	    transform?: (val: number | null | string, series: DataSeries[], idx: number) => number | null;
232	    /** Should show series in tooltip, added to implement more flexible patterns of lines hiding */
233	    showInTooltip?: boolean;
234	    /** Should show series in legend, added to implement more flexible patterns of lines hiding */
235	    showInLegend?: boolean;
236	    /** Should show series on graph (render the line), added to implement more flexible patterns of lines hiding */
237	    showInGraph?: boolean;
238	    /**
239	     * Postprocessing function to change actual values (doesn't marks as _transformed series)
240	     * Use at your own risk
241	     **/
242	    postProcess?: (data: (number | null)[], idx: number, y: Yagr) => (number | null)[];
243	    /**
244	     * Determines what data value should be used to get a color for legend and tooltip.
245	     * - `lineColor` indicates that lineColor property should be used
246	     * - `color` indicates that color property should be used
247	     *
248	     * @default 'color'
249	     */
250	    legendColorKey?: 'color' | 'lineColor';
251	}
252	export interface LineSeriesOptions extends CommonSeriesOptions {
253	    type: 'line';
254	    /** Width of line (line type charts) */
255	    width?: number;
256	    /** Area fill style under the line */
257	    fill?: Series.Fill;
258	    /** Interpolation type */
259	    interpolation?: InterpolationType;
260	    /** Should join paths over null-points */
261	    spanGaps?: boolean;
262	}
263	export interface AreaSeriesOptions extends CommonSeriesOptions {
264	    type: 'area';
265	    /** Color of line (area type charts) */
266	    lineColor?: string;
267	    /** Color of line over area (area type charts) */
268	    lineWidth?: number;
269	    /** Interpolation type (default: linear) */
270	    interpolation?: InterpolationType;
271	    /** Should join paths over null-points */
272	    spanGaps?: boolean;
273	}
274	export interface ColumnSeriesOptions extends CommonSeriesOptions {
275	    type: 'column';
276	    /** Bars rendering options */
277	    renderOptions?: Series.BarsPathBuilderOpts;
278	}
