export function appendNextPoint(series: CpuSeries): number {
  const t = series.timeline[series.timeline.length - 1] + POINT_INTERVAL_MS;
  const v = stepValue(series.lastValue, t);
  series.timeline.push(t); series.timeline.shift();
  series.values.push(v); series.values.shift();
  series.lastValue = v;
  return v;
}
