import {Moon, Sun} from '@gravity-ui/icons';

import {CpuChart} from './monitoring/CpuChart';
import './app.css';

interface AppProps {
  theme: 'light' | 'dark';
  onThemeChange: (theme: 'light' | 'dark') => void;
}

export function App({theme, onThemeChange}: AppProps) {
  const [currentCpu, setCurrentCpu] = React.useState<number | null>(null);

  return (
    <div className="page">
      <div className="page__content">
        <Flex as="header" justifyContent="space-between" alignItems="center" className="page__header">
          <Text variant="header-2">Мониторинг</Text>
          <Flex alignItems="center" gap={2}>
            <Icon data={Sun} size={16} className="page__theme-icon" />
            <Switch
              checked={theme === 'dark'}
              onUpdate={(checked) => onThemeChange(checked ? 'dark' : 'light')}
              aria-label="Тёмная тема"
            />
            <Icon data={Moon} size={16} className="page__theme-icon" />
          </Flex>
        </Flex>

        <Card view="raised" size="l" spacing={{p: 5}} className="page__card">
          <Flex justifyContent="space-between" alignItems="baseline" className="page__card-header">
            <Flex direction="column" gap={1}>
              <Text variant="subheader-2">Загрузка CPU</Text>
