export const UPDATE_INTERVAL_MS = 1000;
const WINDOW_MS = 24 * 60 * 60 * 1000;
export const POINTS_COUNT = WINDOW_MS / UPDATE_INTERVAL_MS; // 86400

export interface CpuSeries {
  timeline: number[];
  values: number[];
  lastValue: number;
}

function dailyBaseline(timestamp: number): number {
  const date = new Date(timestamp);
  const hour = date.getHours() + date.getMinutes() / 60 + date.getSeconds() / 3600;
  // дневной пик около 12:00, вечерний около 20:00, ночью минимум
  const day = 18 * Math.exp(-((hour - 12) ** 2) / 18);
  const evening = 14 * Math.exp(-((hour - 20) ** 2) / 8);
  return 22 + day + evening;
}

function step(previous: number, timestamp: number): number {
  const baseline = dailyBaseline(timestamp);
  let value = previous + (baseline - previous) * 0.02 + (Math.random() - 0.5) * 3;
  if (Math.random() < 0.0015) {
    value += 20 + Math.random() * 35; // короткий всплеск нагрузки
  }
  return Math.min(99, Math.max(1, value));
}

export function generateInitialSeries(now: number = Date.now()): CpuSeries {
  const count = Math.round(WINDOW_MS / UPDATE_INTERVAL_MS);
  const timeline = new Array<number>(count);
  const values = new Array<number>(count);
  const start = now - (count - 1) * UPDATE_INTERVAL_MS;
  let value = dailyBaseline(start);
  for (let i = 0; i < count; i++) {
    const t = start + i * UPDATE_INTERVAL_MS;
    value = step(value, t);
    timeline[i] = t;
    values[i] = Math.round(value * 10) / 10;
  }
  return {timeline, values, lastValue: values[count - 1]};
}

export function appendNextPoint(series: CpuSeries): {t: number; value: number} {
  const t = series.timeline[series.timeline.length - 1] + UPDATE_INTERVAL_MS;
  const value = Math.round(step(series.lastValue, t) * 10) / 10;
  series.timeline.push(t);
  series.timeline.shift();
  series.values.push(value);
  series.values.shift();
  series.lastValue = value;
  return {t, value};
}
